CREATE TABLE music_metadata_candidate (id UUID PRIMARY KEY DEFAULT uuid_v7(), owner_id UUID NOT NULL, track_id UUID NOT NULL, attachment_id UUID NOT NULL, title VARCHAR(512), artist VARCHAR(512), album VARCHAR(512), album_artist VARCHAR(512), isrc VARCHAR(64), genre VARCHAR(256), track_number INTEGER, disc_number INTEGER, release_year VARCHAR(16), source VARCHAR(32) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp, version BIGINT NOT NULL DEFAULT 0, CHECK(track_number IS NULL OR track_number>0), CHECK(disc_number IS NULL OR disc_number>0), FOREIGN KEY(track_id) REFERENCES music_track(id), FOREIGN KEY(attachment_id) REFERENCES attachment(id), UNIQUE(owner_id,track_id,attachment_id));
